T = int(input())
for t in range(T):
	N = int(input())
	A = [int(x) for x in input().split()]
	if N == 1:
		A = [1, 1, A[0] - 1]
	elif N == 2:
		A = [1, A[1] + 1, A[0] - 1]
	elif N & 1:
		A.append(1)
		A.append(A[-2] - 1)
		A[-4] -= 1
		A[-3] = 1
	else:
		A.append(A[-2] - 1)
		A[-4] -= 1
		A[-3] = 1
		A[-2] += 1
	while A[-1] == 0:
		A.pop()
	for i in range(len(A) - 2, 0, -1):
		if A[i] == 0:
			A[i - 1] += A[i + 1]
			del A[i:i + 2]
	print(len(A))
	print(' '.join(map(str, A)))
